fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Create a new vector with a length of one greater than the original
    let mut result = Vec::with_capacity(arr.len() + 1);
    
    // Copy elements before the insertion index
    for i in 0..idx {
        result.push(arr[i].clone());
    }
    
    // Insert the new value at the specified index
    result.push(value);
    
    // Copy the remaining elements, shifting them to the right
    for i in idx..arr.len() {
        result.push(arr[i].clone());
    }
    
    result
}